    check(COMBINATIONS.some(c=>c.minutes===session.minutes&&c.profile===session.profile)&&!seen.has(key),'Duplicate/unknown combination');seen.add(key);
    check(run.completion==='completed'&&session.completion==='completed','Partial or interrupted originals cannot satisfy the native matrix');
    check(session.mode==='real-time'&&finite(session.elapsedMs)&&session.elapsedMs>=session.minutes*60_000,'Real elapsed observation is too short or invalid');
    check(typeof run.startedAt==='string'&&Number.isFinite(Date.parse(run.startedAt))&&finite(run.elapsedMs)&&run.elapsedMs>=session.elapsedMs,'Invalid run timestamps');
    check(Number.isSafeInteger(session.inputs)&&session.inputs>=0&&(session.profile!=='idle'||session.inputs===0),'Invalid input count; fresh idle must have zero inputs');
    check(Array.isArray(session.timeline)&&session.timeline.length>0&&object(session.start)&&object(session.end)&&
      session.timeline.every((sample,i)=>finite(sample.elapsedMs)&&sample.elapsedMs>=0&&sample.elapsedMs<=session.elapsedMs&&
        (i===0||sample.elapsedMs>=session.timeline[i-1].elapsedMs)),'Missing or invalid observation timeline');
    const schedule=menuVisitSchedule(session.minutes);
    check(session.journeyPolicy===(schedule.length?'menu-reincarnation-10m':'observe-only'),'Wrong natural-play menu policy');
    check(Array.isArray(session.menuVisits)&&session.menuVisits.length===schedule.length,'Missing or extra natural-play menu visits');
    session.menuVisits.forEach((visit,i)=>{
      check(object(visit)&&visit.scheduledAtMs===schedule[i]&&finite(visit.elapsedMs)&&visit.elapsedMs>=schedule[i]&&
        visit.elapsedMs<=schedule[i]+30_000&&visit.elapsedMs<=session.elapsedMs,'Late, accelerated, or invalid menu visit');
      check(finite(visit.completedAtMs)&&visit.completedAtMs>=visit.elapsedMs&&visit.completedAtMs<=session.elapsedMs&&
        visit.completedAtMs<=schedule[i]+30_000,'Missing or invalid menu completion time');
      check(['not-ready','selected'].includes(visit.action)&&Number.isSafeInteger(visit.reincarnationsBefore)&&visit.reincarnationsBefore>=0&&
        Number.isSafeInteger(visit.reincarnationsAfter)&&visit.reincarnationsAfter===visit.reincarnationsBefore+(visit.action==='selected'?1:0)&&
        (visit.action!=='selected'||typeof visit.formId==='string'&&visit.formId.length>0),'Invalid menu reincarnation transition');
      check(visit.reincarnationsBefore===(i===0?session.start.reincarnations:session.menuVisits[i-1].reincarnationsAfter)&&
        (i===0||visit.elapsedMs>=session.menuVisits[i-1].completedAtMs),'Disconnected menu reincarnation history');
    });
    if(schedule.length) {
      const firstSelected=session.menuVisits.find(visit=>visit.action==='selected');
      check(firstSelected&&finite(session.firstReincarnationElapsedMs)&&session.firstReincarnationElapsedMs>0&&
        session.firstReincarnationElapsedMs<=session.elapsedMs,'Continuous journey never completed a real reincarnation');
      check(session.start.reincarnations===0&&session.end.reincarnations===session.menuVisits.at(-1).reincarnationsAfter,
        'Continuous journey start/end do not match menu history');
      check(session.firstReincarnationElapsedMs===firstSelected.completedAtMs,'First reincarnation time must match the first completed selection');
    }
    check(Array.isArray(run.checks)&&run.checks.length>0&&run.checks.every(c=>object(c)&&typeof c.id==='string'&&c.id.trim()&&c.details!==undefined)&&
      new Set(run.checks.map(c=>c.id)).size===run.checks.length,'Missing or duplicate checks');
    check(run.checks.every(c=>typeof c.passed==='boolean')&&Array.isArray(run.errors),'Invalid check/error status');
    check([...REQUIRED_NATIVE_CHECKS,'real-time-observation'].every(id=>run.checks.some(c=>c.id===id)), 'Missing required native acceptance checks');
    check(['passed','failed'].includes(run.status),'Unknown run status');
    check(run.status!=='passed'||(record.exitCode===0&&run.checks.every(c=>c.passed)&&!run.errors.length),'Failure hidden by passed status');
