  for(let i=1;i<ordered.length;i++)check(Date.parse(ordered[i].startedAt)>=Date.parse(ordered[i-1].startedAt)+ordered[i-1].elapsedMs,'Native runs overlap; sequential desktop execution required');
  const observationMs=sessions.reduce((sum,s)=>sum+s.elapsedMs,0);check(observationMs>=CONFIG.native.minimumObservationMinutes*60_000,'Matrix observation under 330 minutes');
  return {schemaVersion:3,mode:'electron-e2e',sourceDigest:digest,evaluationDigest:toolDigest,command:'node .harness/v7/loop/e2e-matrix.mjs run <directory>',
    startedAt:ordered[0].startedAt,elapsedMs:originals.reduce((sum,r)=>sum+r.elapsedMs,0),observationMs,
    status:!errors.length&&checks.every(c=>c.passed)?'passed':'failed',checks,sessions,screenshots:shots,errors,
    matrix:{version:2,originals},limitations:['Nine independent 5/15/30-minute runs observe without menu choices; fresh idle has zero inputs.',
      'The independent continuous 180-minute active run visits the real hero menu every 10 minutes and selects the first available choice.',
      'Scripted diagnostic fixtures follow natural observation and are not natural acquisitions.',
      'Human fun and interruption remain PENDING; OS hooks, Accessibility and live PvP are separate.']};
}
